	repoOp := deriveRepoOpFromMCPTool(toolName)
	if repoOp == "" {
		repoOp = deriveRepoOpFromCLICommand(firstNonEmpty(resultCommand, hctx.ToolArgs, extractCommandFromStdin(hctx.Input)))
	}
	if repoOp == "" {
		return
	}
	phase := "starting"
